# frozen_string_literal: true

require_relative "test_helper"

# Guards the extracted benchmark catalogs under benchmarks/<cloud>/catalog.json.
#
# These JSON files are generated by tools/extract_benchmark.py from the official
# CIS benchmark PDFs. A regenerated catalog that silently drops a control,
# mislabels an assessment, or leaves pdftotext residue in a title is the exact
# failure mode this test exists to catch.
class BenchmarksTest < CisTestCase
  CLOUDS = {
    "tencent" => { version: "v1.0.0", controls: 91 },
    "aws"     => { version: "v7.0.0", controls: 64 },
    "alibaba" => { version: "v2.0.0", controls: 78 },
    "gcp"     => { version: "v5.0.0", controls: 84 },
    "azure"   => { version: "v6.0.0", controls: 70 },
  }.freeze

  RESIDUE = [
    [/- ([a-z])/,     "hyphenated line break"],
    [/  /,            "collapsed whitespace missing"],
    [/\bo\s+o\b/,     "checkbox glyph"],
  ].freeze

  def catalog_path(cloud)
    File.join(Cis::ROOT, "benchmarks", cloud, "catalog.json")
  end

  def load_catalog(cloud)
    JSON.parse(File.read(catalog_path(cloud)))
  end

  def test_every_cloud_has_a_catalog_with_the_expected_shape
    CLOUDS.each do |cloud, meta|
      assert File.file?(catalog_path(cloud)), "#{cloud}: benchmarks/#{cloud}/catalog.json missing"
      cat = load_catalog(cloud)
      assert_equal meta[:version], cat["version"], "#{cloud} version"
      assert_kind_of Hash,  cat["sections"],  "#{cloud} sections"
      assert_kind_of Array, cat["controls"],  "#{cloud} controls"
      assert_equal meta[:controls], cat["controls"].size, "#{cloud} control count"
    end
  end

  def test_every_cloud_has_exactly_one_benchmark_pdf
    CLOUDS.each_key do |cloud|
      pdfs = Dir.glob(File.join(Cis::ROOT, "benchmarks", cloud, "*.pdf"))
      assert_equal 1, pdfs.size, "#{cloud}: expected one benchmark PDF, got #{pdfs.inspect}"
    end
  end

  def test_control_ids_are_unique_within_each_catalog
    CLOUDS.each_key do |cloud|
      ids = load_catalog(cloud)["controls"].map { |c| c["id"] }
      dups = ids.tally.select { |_id, n| n > 1 }.keys
      assert_empty dups, "#{cloud} duplicate ids: #{dups.sort}"
    end
  end

  def test_two_level_sections_are_contiguous
    CLOUDS.each_key do |cloud|
      cat = load_catalog(cloud)
      cat["controls"].group_by { |c| c["section"] }.each do |sid, grp|
        next unless grp.all? { |c| c["id"].split(".").size == 2 }

        nums = grp.map { |c| Integer(c["id"].split(".")[1]) }.sort
        assert_equal (1..nums.size).to_a, nums, "#{cloud} section #{sid} gap"
      end
    end
  end

  def test_assessment_and_profile_use_the_expected_enum_values
    CLOUDS.each_key do |cloud|
      cat = load_catalog(cloud)
      cat["controls"].each do |c|
        assert_includes %w[Automated Manual], c["assessment"], "#{cloud} #{c['id']} assessment"
        assert_includes %w[Level\ 1 Level\ 2], c["profile"],    "#{cloud} #{c['id']} profile"
      end
    end
  end

  def test_titles_are_free_of_pdftotext_residue
    CLOUDS.each_key do |cloud|
      cat = load_catalog(cloud)
      cat["controls"].each do |c|
        title = c["title"]
        RESIDUE.each do |re, what|
          refute_match re, title, "#{cloud} #{c['id']} title #{what}: #{title.inspect}"
        end
        assert_equal title, title.strip, "#{cloud} #{c['id']} title has outer whitespace"
      end
    end
  end

  def test_group_heading_agrees_with_the_sections_table
    CLOUDS.each_key do |cloud|
      cat = load_catalog(cloud)
      cat["controls"].each do |c|
        parts = c["id"].split(".")
        next unless parts.size == 3

        gid = parts[0, 2].join(".")
        assert_equal cat["sections"][gid], c["group"],
                     "#{cloud} #{c['id']} group mismatch"
      end
    end
  end

  def test_tencent_catalog_matches_the_controls_yml_registry
    cat = load_catalog("tencent")
    registry = Cis.catalog
    cat_ids = cat["controls"].map { |c| c["id"] }.sort
    reg_ids = registry.controls.map(&:id).sort
    assert_equal reg_ids, cat_ids,
                 "tencent catalog and config/controls.yml drifted apart"
  end

  def test_aws_catalog_matches_the_aws_controls_yml_registry
    cat = load_catalog("aws")
    registry = Cis::Catalog.load(File.join(Cis::ROOT, "config", "aws", "controls.yml"))
    cat_ids = cat["controls"].map { |c| c["id"] }.sort
    reg_ids = registry.controls.map(&:id).sort
    assert_equal reg_ids, cat_ids,
                 "aws catalog and config/aws/controls.yml drifted apart"
  end

  def test_azure_catalog_matches_the_azure_controls_yml_registry
    cat = load_catalog("azure")
    registry = Cis::Catalog.load(File.join(Cis::ROOT, "config", "azure", "controls.yml"))
    assert_equal cat["controls"].map { |c| c["id"] }.sort, registry.controls.map(&:id).sort,
                 "azure catalog and config/azure/controls.yml drifted apart"
  end
end
